"use client";
import { useEffect, useLayoutEffect, useSyncExternalStore } from "react";
import { usePathname, useRouter } from "next/navigation";
import { Sun, Moon } from "lucide-react";
import {
  isWorkspacePath,
  parseAppearance,
  type Appearance,
} from "@/lib/appearance";
type Theme = "light" | "dark";
let localChoice: Theme | null = null;
let localAppearance: Appearance | null = null;
let blackThemeAccess = false;
let accessDeadline: string | null = null;
function hasBlackThemeAccess() {
  return (
    blackThemeAccess &&
    (!accessDeadline || Date.now() < Date.parse(accessDeadline))
  );
}
export function useBlackThemes() {
  return useSyncExternalStore(subscribe, hasBlackThemeAccess, () => false);
}
// Both the root server response and fresh workspace entitlements publish here.
export function ThemeAccessSync({
  allowed,
  deadline,
}: {
  allowed: boolean;
  deadline: string | null;
}) {
  useLayoutEffect(() => {
    blackThemeAccess = allowed;
    accessDeadline = deadline;
    ++themeRequest;
    activeTransition?.skipTransition();
    applyAppearance(appearancePreference());
  }, [allowed, deadline]);
  return null;
}
let themeRequest = 0;
let activeTransition: ViewTransition | undefined;
function snapshot(): Theme {
  return document.documentElement.dataset.theme === "dark" ? "dark" : "light";
}
function preference(): Theme | null {
  if (localChoice) return localChoice;
  try {
    const value = localStorage.getItem("mailloop-theme");
    return value === "light" || value === "dark" ? value : localChoice;
  } catch {
    return localChoice;
  }
}
function appearanceSnapshot(): Appearance {
  return parseAppearance(
    document.documentElement.getAttribute("data-appearance"),
  );
}
function savedAppearance(): Appearance {
  if (localAppearance) return localAppearance;
  try {
    const value = localStorage.getItem("mailloop-appearance");
    return parseAppearance(value);
  } catch {
    return "purple";
  }
}
function appearancePreference(): Appearance {
  return hasBlackThemeAccess() ? savedAppearance() : "purple";
}
function updateThemeColor() {
  const pathname = window.location.pathname;
  const landing = pathname === "/" ? document.querySelector(".landing") : null;
  const pricing =
    pathname === "/pricing" ? document.querySelector(".pricing-page") : null;
  const confirmation = pathname === "/usage/return";
  const color = getComputedStyle(landing ?? pricing ?? document.documentElement)
    .getPropertyValue(
      landing
        ? "--landing-bg"
        : pricing
          ? "--bg"
          : confirmation
            ? "--confirmation-bg"
            : "--background",
    )
    .trim();
  document.querySelectorAll('meta[name="theme-color"]').forEach((meta) => {
    if (meta.getAttribute("content") !== color)
      meta.setAttribute("content", color);
  });
}
let themeColorFrame = 0;
function emitChange() {
  window.dispatchEvent(new Event("mailloop-theme"));
  cancelAnimationFrame(themeColorFrame);
  themeColorFrame = requestAnimationFrame(updateThemeColor);
}
function apply(theme: Theme) {
  document.documentElement.dataset.theme = theme;
  emitChange();
}
function applyAppearance(appearance: Appearance) {
  document.documentElement.dataset.appearance = appearance;
  emitChange();
}
export function chooseAppearance(appearance: Appearance, theme: Theme) {
  if (appearance === "vercel" && !hasBlackThemeAccess()) return;
  localChoice = theme;
  localAppearance = appearance;
  try {
    localStorage.setItem("mailloop-appearance", appearance);
    localStorage.setItem("mailloop-theme", theme);
  } catch {
    // The preference remains active for this document when storage is blocked.
  }
  const request = ++themeRequest;
  activeTransition?.skipTransition();
  activeTransition = undefined;
  const root = document.documentElement;
  root.removeAttribute("data-theme-reveal");
  root.style.removeProperty("--theme-reveal-origin");
  root.removeAttribute("data-appearance-transition");
  const update = () => {
    if (request !== themeRequest) return;
    root.dataset.appearance =
      appearance === "vercel" && !hasBlackThemeAccess() ? "purple" : appearance;
    apply(theme);
  };
  if (
    (appearanceSnapshot() === appearance && snapshot() === theme) ||
    !document.startViewTransition ||
    matchMedia("(prefers-reduced-motion: reduce)").matches
  ) {
    update();
    return;
  }
  // Fade the old page over the new palette without animating layout or fonts.
  root.setAttribute("data-appearance-transition", "");
  const transition = document.startViewTransition(update);
  activeTransition = transition;
  const cleanup = () => {
    if (activeTransition !== transition) return;
    activeTransition = undefined;
    root.removeAttribute("data-appearance-transition");
  };
  void transition.finished.then(cleanup, cleanup);
}
function defaultTheme(): Theme {
  return "dark";
}
function subscribe(callback: () => void) {
  window.addEventListener("mailloop-theme", callback);
  return () => window.removeEventListener("mailloop-theme", callback);
}
export function useTheme() {
  return useSyncExternalStore(subscribe, snapshot, () => "dark" as const);
}

export function useAppearance() {
  return useSyncExternalStore(
    subscribe,
    appearanceSnapshot,
    () => "purple" as const,
  );
}

// Mounted once at the root, outside Next's retained route trees. Both initial
// rendering and client navigation explicitly identify the active workspace.
export function ThemeRuntime() {
  const pathname = usePathname();
  const router = useRouter();
  const deadline = useSyncExternalStore(
    subscribe,
    () => accessDeadline,
    () => null,
  );
  useEffect(() => {
    if (!deadline) return;
    let timer: number;
    const expire = () => {
      const remaining = Date.parse(deadline) - Date.now();
      if (remaining > 0) {
        timer = window.setTimeout(expire, Math.min(remaining, 2147483647));
        return;
      }
      // Fail closed while a fresh server response verifies renewal or grace.
      blackThemeAccess = false;
      ++themeRequest;
      activeTransition?.skipTransition();
      applyAppearance("purple");
      window.dispatchEvent(new Event("mailloop:access-refresh"));
      router.refresh();
    };
    expire();
    return () => window.clearTimeout(timer);
  }, [deadline, router]);
  useEffect(() => {
    const refresh = () => {
      if (
        document.visibilityState === "visible" &&
        !isWorkspacePath(window.location.pathname)
      )
        router.refresh();
    };
    window.addEventListener("focus", refresh);
    window.addEventListener("mailloop:access-refresh", refresh);
    document.addEventListener("visibilitychange", refresh);
    return () => {
      window.removeEventListener("focus", refresh);
      window.removeEventListener("mailloop:access-refresh", refresh);
      document.removeEventListener("visibilitychange", refresh);
    };
  }, [router]);
  useLayoutEffect(() => {
    document.documentElement.toggleAttribute("data-themed", pathname !== "/");
    document.documentElement.toggleAttribute(
      "data-workspace",
      isWorkspacePath(pathname),
    );
    applyAppearance(appearancePreference());
    apply(preference() ?? defaultTheme());
  }, [pathname]);
  useEffect(() => {
    const query = matchMedia("(prefers-color-scheme: dark)");
    const system = () => {
      if (!preference()) apply(defaultTheme());
    };
    const storage = (event: StorageEvent) => {
      if (
        event.key &&
        !["mailloop-theme", "mailloop-appearance"].includes(event.key)
      )
        return;
      localChoice = null;
      localAppearance = null;
      ++themeRequest;
      activeTransition?.skipTransition();
      applyAppearance(appearancePreference());
      apply(preference() ?? defaultTheme());
    };
    window.addEventListener("storage", storage);
    query.addEventListener("change", system);
    return () => {
      window.removeEventListener("storage", storage);
      query.removeEventListener("change", system);
    };
  }, []);
  useEffect(() => {
    const selector = 'meta[name="theme-color"]';
    const observer = new MutationObserver((records) => {
      if (
        records.some((record) =>
          record.type === "attributes"
            ? record.target instanceof Element &&
              record.target.matches(selector)
            : Array.from(record.addedNodes).some(
                (node) =>
                  node instanceof Element &&
                  (node.matches(selector) || node.querySelector(selector)),
              ),
        )
      )
        updateThemeColor();
    });
    observer.observe(document, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ["content"],
    });
    updateThemeColor();
    return () => observer.disconnect();
  }, [pathname]);
  return null;
}
export function switchTheme(theme: Theme, button: HTMLButtonElement) {
  localChoice = theme;
  try {
    localStorage.setItem("mailloop-theme", theme);
  } catch {
    /* Remains active in this document. */
  }
  const request = ++themeRequest;
  const root = document.documentElement;
  activeTransition?.skipTransition();
  activeTransition = undefined;
  root.removeAttribute("data-theme-reveal");
  root.removeAttribute("data-appearance-transition");
  root.style.removeProperty("--theme-reveal-origin");
  if (snapshot() === theme) return;
  if (
    !document.startViewTransition ||
    matchMedia("(prefers-reduced-motion: reduce)").matches
  ) {
    apply(theme);
    return;
  }
  const bounds = button.getBoundingClientRect();
  const x = bounds.left + bounds.width / 2,
    y = bounds.top + bounds.height / 2;
  const radius = Math.hypot(
    Math.max(x, innerWidth - x),
    Math.max(y, innerHeight - y),
  );
  // Hide the new snapshot from its first frame, before ready starts the reveal.
  root.style.setProperty("--theme-reveal-origin", `${x}px ${y}px`);
  root.setAttribute("data-theme-reveal", "");
  const transition = document.startViewTransition(() => {
    if (request === themeRequest) apply(theme);
  });
  activeTransition = transition;
  let animation: Animation | undefined;
  const cleanup = () => {
    animation?.cancel();
    if (activeTransition !== transition) return;
    activeTransition = undefined;
    root.removeAttribute("data-theme-reveal");
    root.style.removeProperty("--theme-reveal-origin");
  };
  void transition.finished.then(cleanup, cleanup);
  void transition.ready
    .then(() => {
      if (activeTransition !== transition) return;
      animation = root.animate(
        {
          clipPath: [
            `circle(0px at ${x}px ${y}px)`,
            `circle(${radius}px at ${x}px ${y}px)`,
          ],
        },
        {
          duration: 480,
          easing: "cubic-bezier(.4,0,.2,1)",
          fill: "both",
          pseudoElement: "::view-transition-new(root)",
        },
      );
    })
    .catch(() => {
      // A failed reveal should still leave the selected theme visible.
      transition.skipTransition();
    });
}
export function ThemeControl() {
  const theme = useSyncExternalStore(subscribe, snapshot, () => "light");
  return (
    <div className="inline-flex items-center gap-3">
      <div
        className="theme-track relative flex p-1 [border:1px_solid_var(--border)] rounded-full [background:var(--surface)]"
        role="group"
        aria-label="Theme"
      >
        <span
          className="theme-thumb [background:var(--accent-gradient)] text-primary-foreground shadow-[0_8px_22px_color-mix(in_srgb,_var(--accent)_38%,_transparent)] absolute top-1 left-1 w-11 h-11 rounded-full"
          aria-hidden="true"
        />
        {(["light", "dark"] as const).map((value) => (
          <button
            type="button"
            key={value}
            aria-label={`${value === "light" ? "Light" : "Dark"} theme`}
            aria-pressed={theme === value}
            onClick={(event) => switchTheme(value, event.currentTarget)}
          >
            {value === "light" ? (
              <Sun aria-hidden="true" />
            ) : (
              <Moon aria-hidden="true" />
            )}
          </button>
        ))}
      </div>
    </div>
  );
}
